-- =====================================================================
-- EXECUTIVE DASHBOARD — DELIVERY MARGIN SEED (Alt A+ Unified Schema)
-- =====================================================================
-- Strategy: Extend FACT_METRIC with multi-metric support (additive).
-- Backward compatible — existing EBITDA seed continues to work unchanged.
--
-- Naming conventions:
--   FM_METRIC_NAME    : UPPERCASE_SNAKE_CASE (GROSS_SALES, NETT_SALES, etc.)
--   FM_METRIC_CATEGORY: VOLUME | VALUE | AVERAGE | RATIO | DERIVED
--   FM_AGG_METHOD     : SUM | WEIGHTED_AVG | AVG | LAST | RATIO
--   FM_TYPE           : UPPERCASE (MIS, SALES, INV, HR, PROD, OPEX)
--
-- Source: DELIVERY_MARGIN_DASHBOARD.xlsx (user-normalized to long format)
-- Coverage: 29 months (202401-202605) × 519 dimension combos × 6 metrics = 3,114 rows
--
-- Run AFTER seed_database.sql (this is incremental, not standalone).
-- =====================================================================

-- =====================================================================
-- 1. SCHEMA EXTENSION (idempotent, safe to re-run)
-- =====================================================================

ALTER TABLE FACT_METRIC DROP CONSTRAINT IF EXISTS UQ_FM_BUSINESS_KEY;

ALTER TABLE FACT_METRIC
  ADD COLUMN IF NOT EXISTS FM_METRIC_NAME     VARCHAR(50) NOT NULL DEFAULT 'VALUE',
  ADD COLUMN IF NOT EXISTS FM_METRIC_CATEGORY VARCHAR(20) NOT NULL DEFAULT 'VALUE',
  ADD COLUMN IF NOT EXISTS FM_AGG_METHOD      VARCHAR(20) NOT NULL DEFAULT 'SUM';

COMMENT ON COLUMN FACT_METRIC.FM_METRIC_NAME IS
  'Specific metric within a dimension combination. Default ''VALUE'' for single-metric data (EBITDA). UPPERCASE_SNAKE_CASE convention.';
COMMENT ON COLUMN FACT_METRIC.FM_METRIC_CATEGORY IS
  'Classification: VOLUME (PCS/HOURS), VALUE (currency), AVERAGE (per-unit), RATIO (%), DERIVED (computed).';
COMMENT ON COLUMN FACT_METRIC.FM_AGG_METHOD IS
  'How to aggregate across dimensions: SUM (default), WEIGHTED_AVG, AVG, LAST, RATIO.';

ALTER TABLE FACT_METRIC ADD CONSTRAINT UQ_FM_BUSINESS_KEY UNIQUE
  (FM_TYPE, FM_GROUP_1, FM_GROUP_2, FM_GROUP_3,
   FM_PERIODE_GRAIN, FM_PERIODE_DATE, FM_METRIC_NAME, FM_SCENARIO, FM_DIMENSION_KEY);

CREATE INDEX IF NOT EXISTS IDX_FM_METRIC_NAME ON FACT_METRIC(FM_TYPE, FM_METRIC_NAME, FM_PERIODE_DATE);

-- =====================================================================
-- 2. METRIC REGISTRY TABLE — display labels & metadata
-- =====================================================================
-- Centralized metadata about each metric for use by API and frontend.
-- Separate from FACT_METRIC to avoid string repetition and enable updates
-- to display labels without rewriting fact data.

CREATE TABLE IF NOT EXISTS METRIC_REGISTRY (
  MR_METRIC_ID         SERIAL PRIMARY KEY,
  MR_METRIC_NAME       VARCHAR(50)  UNIQUE NOT NULL,
  MR_DISPLAY_LABEL     VARCHAR(100) NOT NULL,
  MR_METRIC_CATEGORY   VARCHAR(20)  NOT NULL,
  MR_AGG_METHOD        VARCHAR(20)  NOT NULL,
  MR_UOM               VARCHAR(20),
  MR_DESCRIPTION       TEXT,
  MR_NUMBER_FORMAT     VARCHAR(50),
  MR_IS_ACTIVE         BOOLEAN DEFAULT TRUE,
  MR_CREATED_DATE      TIMESTAMP DEFAULT NOW()
);

INSERT INTO METRIC_REGISTRY (
  MR_METRIC_NAME, MR_DISPLAY_LABEL, MR_METRIC_CATEGORY, MR_AGG_METHOD, MR_UOM, MR_DESCRIPTION, MR_NUMBER_FORMAT
) VALUES
  ('VALUE',         'Value',           'VALUE',  'SUM', 'USD', 'Generic single-metric (EBITDA/Net Profit pattern)', 'currency_thousands'),
  ('QUANTITY',      'Quantity',        'VOLUME', 'SUM', 'PCS', 'Quantity in pieces', 'integer_thousands'),
  ('GROSS_SALES',   'Gross Sales',     'VALUE',  'SUM', 'USD', 'Total gross sales before deductions', 'currency_thousands'),
  ('SELLING_COST',  'Selling Cost',    'VALUE',  'SUM', 'USD', 'Direct selling cost (commission, freight, etc.)', 'currency_thousands'),
  ('NETT_SALES',    'Net Sales',       'VALUE',  'SUM', 'USD', 'Gross sales minus selling cost', 'currency_thousands'),
  ('COST_PROD',     'Production Cost', 'VALUE',  'SUM', 'USD', 'Total production cost of goods sold', 'currency_thousands'),
  ('MARGIN',        'Margin',          'VALUE',  'SUM', 'USD', 'Net sales minus production cost (absolute margin)', 'currency_thousands')
ON CONFLICT (MR_METRIC_NAME) DO NOTHING;

